examples.template:
MonarchButton(text = {{trigger}}, onClick = { confirming = true }, variant = MonarchButtonVariant.Danger)
if (confirming) {
    MonarchDialog(
        onDismissRequest = { confirming = false },
        title = {{title}},
        description = {{description}},
        icon = { MonarchIcon(SampleIcons.Warning, contentDescription = null, tint = MonarchTheme.colors.dangerStrong) },
        actions = {
            MonarchButton(text = {{cancelLabel}}, onClick = { confirming = false }, variant = MonarchButtonVariant.Ghost)
            MonarchButton(
                text = {{confirmLabel}},
                onClick = {
                    deleted = true
                    confirming = false
                },
                variant = MonarchButtonVariant.Danger,
                enabled = MonarchTypeToConfirmInputDefaults.matches(typed, {{confirmPhrase}}),
            )
        },
    ) {
        MonarchText(text = {{consequences.0}})
        MonarchText(text = {{consequences.1}})
        MonarchText(text = {{consequences.2}})
        MonarchTypeToConfirmInput(phrase = {{confirmPhrase}}, value = typed, onValueChange = { typed = it })
    }
}

