examples.setup:
var confirming by remember { mutableStateOf(true) }
var phrase by remember { mutableStateOf("") }
var deleting by remember { mutableStateOf(false) }

examples.code:
if (confirming) {
    MonarchDialog(
        onDismissRequest = { confirming = false },
        title = "Delete the workspace?",
        description = "The workspace and everything in it are deleted. Type DELETE to confirm.",
        // While it is deleted, back and a tap outside do not close it; a tap outside never loses the typed phrase.
        dismissible = !deleting,
        dismissOnClickOutside = false,
        actions = {
            MonarchButton(
                text = "Cancel",
                onClick = { confirming = false },
                variant = MonarchButtonVariant.Ghost,
                enabled = !deleting,
            )
            MonarchButton(
                text = "Delete",
                onClick = { deleting = true },
                variant = MonarchButtonVariant.Danger,
                enabled = phrase == "DELETE",
                loading = deleting,
            )
        },
    ) {
        MonarchTextField(
            value = phrase,
            onValueChange = { phrase = it },
            label = "Confirmation",
            enabled = !deleting,
        )
    }
}
